```typescript
import { LucideIcon } from 'lucide-react';

export interface SubItem {
  icon?: LucideIcon;
  label: string;
  amount: number;
}

interface MetricCardProps {
  label: string;
  amount: number;
  icon: LucideIcon;
  iconColor: string;
  accentColor: string;
  textColor?: string;
  subItems?: SubItem[];
}

export const MetricCard: React.FC<MetricCardProps> = ({
  label,
  amount,
  icon: Icon,
  iconColor,
  accentColor,
  textColor,
  subItems
}) => {

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(val);
  };

  return (
    <div className={`group relative bg-zinc-800/40 p-5 rounded-xl border border-zinc-700/50 shadow-sm w-full min-h-[7rem] flex flex-col justify-between overflow-hidden transition-colors hover:border-zinc-600 hover:bg-zinc-800/60`}>

      {/* Subtle indicator bar on left */}
      <div className={`absolute left-0 top-3 bottom-0 w-1 ${accentColor}`}></div>

      <div>
        <div className="flex items-center gap-2 mb-2">
          <Icon size={18} color={iconColor} />
          <span className="text-sm font-medium text-zinc-400">{label}</span>
        </div>
        <div className="text-2xl font-semibold leading-7 tracking-tight">{formatCurrency(amount)}</div>
      </div>

      {/* Sub-items section */}
      {subItems && (
        <div className="mt-4 space-y-1 text-sm text-zinc-400">
          {subItems.map((item, index) => (
            <div key={index} className="flex items-center gap-2">
              {item.icon && <item.icon className="sub-item-icon" />}
              <span>{item.label}</span>
              <span className="ml-auto">{formatCurrency(item.amount)}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};
```


