import React, { useEffect, useRef } from 'react';

interface OrbProps {
  hue?: number;
  size?: number;
  speed?: number;
  className?: string;
}

export const Orb: React.FC<OrbProps> = ({ 
  hue = 270, 
  size = 600, 
  speed = 0.005,
  className = "" 
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;
    let time = 0;

    // Set canvas size (handled by resize observer for responsiveness, but init here)
    const updateSize = () => {
        canvas.width = size;
        canvas.height = size;
    };
    updateSize();

    const draw = () => {
      time += speed;
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const centerX = canvas.width / 2;
      const centerY = canvas.height / 2;
      const radius = canvas.width / 3;

      // Create dynamic gradient
      // Moving the center of the gradient slightly in a circle
      const gradientX = centerX + Math.sin(time) * 50;
      const gradientY = centerY + Math.cos(time * 0.7) * 50;

      const gradient = ctx.createRadialGradient(
        gradientX, 
        gradientY, 
        0, 
        centerX, 
        centerY, 
        radius * 1.5
      );

      // Core color
      gradient.addColorStop(0, `hsla(${hue}, 80%, 70%, 0.8)`);
      // Mid glow
      gradient.addColorStop(0.5, `hsla(${hue + 20}, 70%, 50%, 0.3)`);
      // Outer fade
      gradient.addColorStop(1, 'hsla(0, 0%, 0%, 0)');

      ctx.fillStyle = gradient;
      // Use blur for extra softness
      ctx.filter = 'blur(40px)';

      ctx.beginPath();
      ctx.arc(centerX, centerY, radius * 1.5, 0, Math.PI * 2);
      ctx.fill();

      animationFrameId = requestAnimationFrame(draw);
    };

    draw();

    return () => {
      cancelAnimationFrame(animationFrameId);
    };
  }, [hue, size, speed]);

  return (
    <div 
      ref={containerRef} 
      className={`pointer-events-none absolute opacity-60 mix-blend-screen ${className}`}
      style={{
        width: size,
        height: size,
      }}
    >
      <canvas ref={canvasRef} />
    </div>
  );
};

