    draw();

    return () => {
      cancelAnimationFrame(animationFrameId);
    };
  }, [hue, size, speed]);

  return (
    <div 
      ref={containerRef} 
      className={`pointer-events-none absolute opacity-80 mix-blend-screen will-change-transform ${className}`}
      style={{
        width: size,
        height: size,
      }}
    >
      <canvas ref={canvasRef} />
    </div>
  );
};

