import React, { useState, useEffect } from 'react';
import { X, Save, Wallet, CreditCard, LayoutDashboard } from 'lucide-react';
import { FinancialData } from '../types';

interface AddReportModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (data: FinancialData) => void;
  initialData: FinancialData;
}

export const AddReportModal: React.FC<AddReportModalProps> = ({
  isOpen,
  onClose,
  onSave,
  initialData
}) => {
  const [formData, setFormData] = useState<FinancialData>(initialData);

  useEffect(() => {
    if (isOpen) {
      setFormData(initialData);
    }
  }, [isOpen, initialData]);

  const handleChange = (field: keyof FinancialData, value: string) => {
    setFormData(prev => ({
      ...prev,
      [field]: parseFloat(value) || 0
    }));
  };

  const handleNestedChange = (
    parent: 'shippingBreakdown' | 'dailyShippingBreakdown',
    field: 'card' | 'balance',
    value: string
  ) => {
    const numValue = parseFloat(value) || 0;
    setFormData(prev => {
      const updatedParent = { ...prev[parent], [field]: numValue };

      // Auto-calculate totals
      const updates: Partial<FinancialData> = { [parent]: updatedParent };

      if (parent === 'shippingBreakdown') {
        updates.shipping = updatedParent.card + updatedParent.balance;
      } else if (parent === 'dailyShippingBreakdown') {
        updates.dailyShipping = updatedParent.card + updatedParent.balance;
      }

      return { ...prev, ...updates };
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(formData);
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/60 backdrop-blur-md transition-opacity" 
