              <InputGroup label="Platform Fees" value={formData.sellingFee} onChange={(v) => handleChange('sellingFee', v)} icon="-" />
              <InputGroup label="Cost of Goods (COGS)" value={formData.cogs} onChange={(v) => handleChange('cogs', v)} icon="-" />
            </div>

            {/* Shipping Breakdown */}
            <div className="mt-4 p-4 rounded-xl bg-white/5 border border-white/5">
              <label className="block text-xs text-zinc-400 mb-3 uppercase tracking-wide">Shipping Costs</label>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                 <InputGroup 
                   label="Paid via Card" 
                   value={formData.shippingBreakdown.card} 
                   onChange={(v) => handleNestedChange('shippingBreakdown', 'card', v)}
