                   icon={<CreditCard size={14} />} 
                 />
                 <InputGroup 
                   label="Paid via Balance" 
                   value={formData.dailyShippingBreakdown.balance} 
                   onChange={(v) => handleNestedChange('dailyShippingBreakdown', 'balance', v)}
                   icon={<Wallet size={14} />} 
