import { X, Save, Wallet, CreditCard, LayoutDashboard, Plus, Trash2 } from 'lucide-react';
import { FinancialData, ShippingBreakdown } from '../types';

interface AddReportModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (data: FinancialData) => void;
  initialData: FinancialData;
}

export const AddReportModal: React.FC<AddReportModalProps> = ({
  isOpen,
  onClose,
  onSave,
  initialData
}) => {
  const [formData, setFormData] = useState<FinancialData>(initialData);

  useEffect(() => {
    if (isOpen) {
      setFormData(initialData);
    }
  }, [isOpen, initialData]);

  const handleChange = (field: keyof FinancialData, value: string) => {
    setFormData(prev => ({
      ...prev,
      [field]: parseFloat(value) || 0
    }));
  };

  const handleShippingChange = (
    field: 'shippingBreakdown' | 'dailyShippingBreakdown',
    newBreakdown: ShippingBreakdown
  ) => {
    setFormData(prev => {
      // Calculate total for this specific breakdown
      const total = newBreakdown.cards.reduce((sum, c) => sum + c.amount, 0) + newBreakdown.balance;

      const updates: Partial<FinancialData> = { [field]: newBreakdown };

      // Update total corresponding top-level field
      if (field === 'shippingBreakdown') {
        updates.shipping = total;
      } else if (field === 'dailyShippingBreakdown') {
        updates.dailyShipping = total;
      }

      return { ...prev, ...updates };
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(formData);
    onClose();
