export const AddReportModal: React.FC<AddReportModalProps> = ({
  isOpen,
  onClose,
  onSave,
  initialData
}) => {
  const [formData, setFormData] = useState<FinancialData>(initialData);

  useEffect(() => {
    if (isOpen) {
      setFormData(initialData);
    }
