const App: React.FC = () => {
  // Store reports indexed by date string (YYYY-MM-DD)
  const [reports, setReports] = useState<Record<string, FinancialData>>(INITIAL_DATA);

  // State for which date is currently selected
  const [selectedDate, setSelectedDate] = useState<string>(getTodayString());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);

  // Fetch data from Firebase on mount
  useEffect(() => {
    const fetchData = async () => {
      try {
        const querySnapshot = await getDocs(collection(db, "dailyReports"));
        const fetchedReports: Record<string, FinancialData> = {};

        querySnapshot.forEach((doc) => {
          const data = doc.data();
          // Construct the object to match FinancialData interface safely
          fetchedReports[doc.id] = {
            date: data.date,
            sales: data.sales,
            sellingFee: data.sellingFee,
            cogs: data.cogs,
            shipping: data.shipping,
            dailyInvestment: data.dailyInvestment,
            expectedDailyEarning: data.expectedDailyEarning,
            expectedWeeklyPayout: data.expectedWeeklyPayout,
            previousWeeksPayout: data.previousWeeksPayout,
            shippingBreakdown: data.shippingBreakdown
          } as FinancialData;
        });

        if (Object.keys(fetchedReports).length > 0) {
          setReports(fetchedReports);

          // If today exists in fetched data, select it, otherwise stay on default
          const today = getTodayString();
          if (fetchedReports[today]) {
             setSelectedDate(today);
          } else {
             // If we have data but not for today, optionally switch to the latest one
             // For now we keep default behavior or logic to switch to today if creating new
          }
        }
      } catch (error) {
        console.error("Error fetching data: ", error);
      }
    };

    fetchData();
  }, []);

  // Get list of sorted dates (newest first)
  const availableDates = useMemo(() => {
    return Object.keys(reports).sort((a, b) => new Date(b).getTime() - new Date(a).getTime());
  }, [reports]);

  // If the selected date exists in reports, use it. Otherwise fall back to a default structure for that date.
  const currentData = useMemo(() => {
    return reports[selectedDate] || {
      date: selectedDate,
      sales: 0,
      sellingFee: 0,
      cogs: 0,
      shipping: 0,
      dailyInvestment: 0,
      expectedDailyEarning: 0,
      expectedWeeklyPayout: 0,
      previousWeeksPayout: 0,
      shippingBreakdown: { cards: [], balance: 0 }
    };
  }, [reports, selectedDate]);

  const profit = currentData.sales - (currentData.sellingFee + currentData.cogs + currentData.shipping);
  const totalDailyExpenditure = currentData.dailyInvestment + currentData.shipping;

  const reportRef = useRef<HTMLDivElement>(null);

  const handleSaveReport = async (newData: FinancialData) => {
    // Optimistic update
    setReports(prev => ({
      ...prev,
      [newData.date]: newData
    }));
    setSelectedDate(newData.date);

    try {
      await setDoc(doc(db, "dailyReports", newData.date), {
        ...newData,
        createdAt: serverTimestamp()
      });
    } catch (error) {
      console.error("Error saving document: ", error);
      alert("Failed to save report to database. Please check your connection.");
    }
  };

  const getShippingBreakdown = (breakdown: ShippingBreakdown): SubItem[] => {
    const cardItems = breakdown.cards.map(card => ({
      icon: CreditCard,
      label: `Card •• ${card.last4}`,
      amount: card.amount
    }));

    return [
      ...cardItems,
      { icon: Wallet, label: 'Seller Balance', amount: breakdown.balance }
    ];
  };

  const formatDateDisplay = (dateStr: string) => {
    const date = new Date(dateStr);
    return new Intl.DateTimeFormat('en-US', { month: 'long', day: 'numeric', year: 'numeric' }).format(date);
  };

  return (
    <div className="min-h-screen bg-black text-zinc-100 flex flex-col items-center justify-center p-4 md:p-8 relative selection:bg-cyan-500/30 overflow-x-hidden font-sans">

      {/* Noise Texture Overlay */}
      <div 
        className="fixed inset-0 z-[1] pointer-events-none mix-blend-overlay opacity-30"
        style={{ backgroundImage: `url("${NOISE_SVG}")` }}
      ></div>

      {/* Background Gradients */}
      <div className="fixed inset-0 z-0 pointer-events-none bg-[radial-gradient(circle_at_50%_50%,_rgba(20,20,30,1),_rgba(0,0,0,1))]"></div>

