          {/* Daily Earning Panel */}
          <div className="relative rounded-3xl border border-white/5 bg-white/5 p-6 md:p-8 flex flex-col h-full backdrop-blur-2xl shadow-xl transition-all hover:bg-white/[0.07]">
             <div className="absolute inset-0 rounded-3xl bg-gradient-to-br from-white/5 to-transparent pointer-events-none"></div>

            <div className="relative z-10 flex items-center gap-3 mb-6 pb-4 border-b border-white/10">
              <div className="p-2 bg-emerald-500/10 rounded-xl border border-emerald-500/20 text-emerald-300 shadow-[0_0_15px_rgba(16,185,129,0.1)]">
                <Calendar size={20} />
              </div>
              <h2 className="text-xl font-light text-zinc-100">Daily Earning</h2>
            </div>

            <div className="relative z-10 space-y-4 flex-1">
              <MetricCard 
                label="Expected Daily Earning" 
                amount={currentData.expectedDailyEarning} 
                icon={TrendingUp}
                iconColor="text-emerald-300/80"
                accentColor="bg-emerald-500" 
              />
              <MetricCard 
                label="Expected Weekly Payout" 
                amount={currentData.expectedWeeklyPayout} 
                icon={DollarSign}
                iconColor="text-emerald-300/80"
                accentColor="bg-emerald-500" 
