            </div>
             <div className="relative z-10 mt-6 pt-4 border-t border-white/10 flex justify-between items-center text-emerald-200/80">
                <span className="text-xs font-mono uppercase tracking-wider">Previous Week's Payout</span>
                <span className="text-xl font-light tabular-nums drop-shadow-lg">
                   {new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(currentData.previousWeeksPayout)}
                </span>
             </div>
          </div>

        </div>

        {/* Footer */}
        <div className="flex justify-between items-center px-4 py-6 border-t border-white/5">
           <div></div>
           <div className="flex gap-2 opacity-50">
             <div className="w-1.5 h-1.5 rounded-full bg-white/50"></div>
             <div className="w-1.5 h-1.5 rounded-full bg-white/30"></div>
             <div className="w-1.5 h-1.5 rounded-full bg-white/10"></div>
           </div>
        </div>

      </div>

      <AddReportModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveReport}
        initialData={currentData}
      />
    </div>
  );
};

