        initialData={currentData}
      />
    </div>
  );
};

export default App;

import React, { useState, useRef, useMemo, useEffect } from 'react';
import { 
  DollarSign,
  TrendingUp,
  Wallet,
  CreditCard,
  Archive,
  Truck,
  PieChart,
  Activity,
  Calendar,
  Plus,
  ChevronDown,
  History,
  Copy,
  Check
} from 'lucide-react';
import { MetricCard, SubItem } from './components/MetricCard';
import { Orb } from './components/Orb';
import { AddReportModal } from './components/AddReportModal';
import { FinancialData, ShippingBreakdown } from './types';
import { db } from './firebase';
import { collection, doc, setDoc, getDocs, getDoc, serverTimestamp } from 'firebase/firestore';
import html2canvas from 'html2canvas';

// Noise SVG data URI for grain effect
const NOISE_SVG = `data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)' opacity='0.05'/%3E%3C/svg%3E`;

const Operator: React.FC<{ symbol: string }> = ({ symbol }) => (
  <div className="flex items-center justify-center px-2 shrink-0">
    <span className="text-white/30 text-4xl font-thin select-none drop-shadow-[0_0_5px_rgba(255,255,255,0.1)]">{symbol}</span>
  </div>
);

// Helper to get today's date string YYYY-MM-DD
const getTodayString = () => new Date().toISOString().split('T')[0];

const App: React.FC = () => {
  // Store reports indexed by date string (YYYY-MM-DD)
  // Initialized empty to remove sample data
  const [reports, setReports] = useState<Record<string, FinancialData>>({});

  // State for which date is currently selected
  const [selectedDate, setSelectedDate] = useState<string>(getTodayString());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [isCopying, setIsCopying] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);

  // Fetch all data from Firebase on mount to populate history
  useEffect(() => {
    const fetchAllData = async () => {
      try {
        const querySnapshot = await getDocs(collection(db, "dailyReports"));
        const fetchedReports: Record<string, FinancialData> = {};

        querySnapshot.forEach((doc) => {
          const data = doc.data();
          fetchedReports[doc.id] = {
            date: data.date,
            sales: data.sales,
            sellingFee: data.sellingFee,
            cogs: data.cogs,
            shipping: data.shipping,
            dailyInvestment: data.dailyInvestment,
            expectedDailyEarning: data.expectedDailyEarning,
            expectedWeeklyPayout: data.expectedWeeklyPayout,
            previousWeeksPayout: data.previousWeeksPayout,
            shippingBreakdown: data.shippingBreakdown
          } as FinancialData;
        });

        if (Object.keys(fetchedReports).length > 0) {
          setReports(prev => ({ ...prev, ...fetchedReports }));

          // If today exists in fetched data, select it
          const today = getTodayString();
          if (fetchedReports[today]) {
             setSelectedDate(today);
          }
        }
      } catch (error) {
        console.error("Error fetching history: ", error);
      }
    };

    fetchAllData();
  }, []);

  // Fetch specific document when selectedDate changes
  useEffect(() => {
    const fetchSelectedReport = async () => {
      if (!selectedDate) return;

      try {
        const docRef = doc(db, "dailyReports", selectedDate);
        const docSnap = await getDoc(docRef);

        if (docSnap.exists()) {
          const data = docSnap.data();
          const loadedData = {
            date: data.date,
            sales: data.sales,
            sellingFee: data.sellingFee,
            cogs: data.cogs,
            shipping: data.shipping,
            dailyInvestment: data.dailyInvestment,
            expectedDailyEarning: data.expectedDailyEarning,
            expectedWeeklyPayout: data.expectedWeeklyPayout,
            previousWeeksPayout: data.previousWeeksPayout,
            shippingBreakdown: data.shippingBreakdown
          } as FinancialData;

          setReports(prev => ({
            ...prev,
            [selectedDate]: loadedData
          }));
          console.log("Loaded successfully");
        } else {
          console.log("No data found for date");
          // Logic for reset is handled by currentData memo falling back to defaults 
          // if the key is missing from 'reports'.
        }
      } catch (error) {
        console.error("Error loading report:", error);
      }
    };

    fetchSelectedReport();
  }, [selectedDate]);

  // Get list of sorted dates (newest first)
  const availableDates = useMemo(() => {
    return Object.keys(reports).sort((a, b) => new Date(b).getTime() - new Date(a).getTime());
  }, [reports]);

  // If the selected date exists in reports, use it. Otherwise fall back to a default structure for that date.
  const currentData = useMemo(() => {
    return reports[selectedDate] || {
      date: selectedDate,
      sales: 0,
      sellingFee: 0,
      cogs: 0,
      shipping: 0,
      dailyInvestment: 0,
      expectedDailyEarning: 0,
      expectedWeeklyPayout: 0,
      previousWeeksPayout: 0,
      shippingBreakdown: { cards: [], balance: 0 }
    };
  }, [reports, selectedDate]);

  const profit = currentData.sales - (currentData.sellingFee + currentData.cogs + currentData.shipping);
  const totalDailyExpenditure = currentData.dailyInvestment + currentData.shipping;

  const reportRef = useRef<HTMLDivElement>(null);

  const handleSaveReport = async (newData: FinancialData) => {
    // Optimistic update
    setReports(prev => ({
      ...prev,
      [newData.date]: newData
    }));
    setSelectedDate(newData.date);

    try {
      await setDoc(doc(db, "dailyReports", newData.date), {
        ...newData,
        createdAt: serverTimestamp()
      });
      console.log("Saved successfully");
    } catch (error) {
      console.error("Error saving document: ", error);
      alert("Failed to save report. Please check your connection.");
    }
  };

  const handleCopyReport = async () => {
    if (!reportRef.current || isCopying) return;

    setIsCopying(true);
    try {
      // Small delay to ensure any rendering is finished
      await new Promise(resolve => setTimeout(resolve, 100));

      const canvas = await html2canvas(reportRef.current, {
        backgroundColor: '#09090b', // zinc-950 to match theme
        scale: 2, // High resolution for Retina displays
        logging: false,
        useCORS: true,
        allowTaint: true,
        onclone: (clonedDoc) => {
          // Optional: Manipulate cloned DOM before screenshot if needed
          const element = clonedDoc.querySelector('[data-report-container]') as HTMLElement;
          if (element) {
            element.style.padding = "20px";
            element.style.borderRadius = "24px";
          }
        }
      });

      canvas.toBlob(async (blob) => {
        if (!blob) {
            console.error("Canvas to blob failed");
            return;
        }

        try {
          // Use the Clipboard API to write the image
          await navigator.clipboard.write([
            new ClipboardItem({
              [blob.type]: blob
            })
          ]);
          setCopySuccess(true);
          setTimeout(() => setCopySuccess(false), 2000);
        } catch (err) {
          console.error("Clipboard write failed", err);
          alert("Could not copy image to clipboard. Browser may not support it.");
        }
      }, 'image/png');
    } catch (err) {
      console.error("Screenshot failed", err);
      alert("Failed to generate screenshot.");
    } finally {
      setIsCopying(false);
    }
  };

  const getShippingBreakdown = (breakdown: ShippingBreakdown): SubItem[] => {
    const cardItems = breakdown?.cards?.map(card => ({
      icon: CreditCard,
      label: `Card •• ${card.last4}`,
      amount: card.amount
    })) || [];

    if (breakdown?.balance) {
      cardItems.push({ icon: Wallet, label: 'Seller Balance', amount: breakdown.balance });
    }

    return cardItems;
  };

  const formatDateDisplay = (dateStr: string) => {
    const date = new Date(dateStr);
    return new Intl.DateTimeFormat('en-US', { month: 'long', day: 'numeric', year: 'numeric' }).format(date);
  };

  return (
    <div className="min-h-screen bg-black text-zinc-100 flex flex-col items-center justify-center p-4 md:p-8 relative selection:bg-cyan-500/30 overflow-x-hidden font-sans">

      {/* Noise Texture Overlay */}
      <div 
        className="fixed inset-0 z-[1] pointer-events-none mix-blend-overlay opacity-30"
        style={{ backgroundImage: `url("${NOISE_SVG}")` }}
      ></div>

      {/* Background Gradients */}
      <div className="fixed inset-0 z-0 pointer-events-none bg-[radial-gradient(circle_at_50%_50%,_rgba(20,20,30,1),_rgba(0,0,0,1))]"></div>

      {/* Decorative Orbs */}
      <Orb hue={280} size={900} speed={0.004} className="top-[-30%] left-[-20%] md:top-[-40%] md:left-[-20%] animate-pulse-slow" />
      <Orb hue={180} size={800} speed={0.006} className="bottom-[-30%] right-[-20%] md:bottom-[-40%] md:right-[-20%]" />
      <Orb hue={320} size={400} speed={0.008} className="top-[20%] right-[10%] opacity-40" />

      {/* Logo */}
      <div className="absolute top-6 left-6 z-50">
        <img 
          src="https://app.kambojventures.com/assets/images/logos/logo.png" 
          alt="Kamboj Ventures" 
          className="h-12 w-auto drop-shadow-lg opacity-90 hover:opacity-100 transition-opacity"
        />
      </div>

      {/* Top Right Controls */}
      <div className="absolute top-6 right-6 z-50 flex items-center gap-3">

        {/* Copy Report Button */}
        <button
          onClick={handleCopyReport}
          disabled={isCopying}
          className={`flex items-center gap-2 px-4 py-2.5 rounded-full border transition-all duration-300 backdrop-blur-md ${
            copySuccess 
              ? 'bg-emerald-500/20 border-emerald-500/30 text-emerald-300' 
              : 'bg-white/5 border-white/10 hover:bg-white/10 text-zinc-300 hover:text-white'
          }`}
          title="Copy Report Screenshot"
        >
          {copySuccess ? <Check size={16} /> : <Copy size={16} />}
          <span className="text-sm font-medium hidden sm:inline">
            {isCopying ? 'Copying...' : copySuccess ? 'Copied' : 'Copy Report'}
          </span>
        </button>

        {/* Date Selector / History */}
        <div className="relative">
          <button 
            onClick={() => setIsHistoryOpen(!isHistoryOpen)}
            className="flex items-center gap-2 px-4 py-2.5 rounded-full bg-white/5 border border-white/10 hover:bg-white/10 transition-all backdrop-blur-md"
          >
            <History size={16} className="text-zinc-400" />
            <span className="text-sm font-medium text-zinc-200">{formatDateDisplay(selectedDate)}</span>
            <ChevronDown size={14} className={`text-zinc-500 transition-transform ${isHistoryOpen ? 'rotate-180' : ''}`} />
          </button>

          {isHistoryOpen && (
            <>
              <div className="fixed inset-0 z-40" onClick={() => setIsHistoryOpen(false)}></div>
              <div className="absolute top-full right-0 mt-2 w-56 max-h-64 overflow-y-auto bg-zinc-900/95 border border-white/10 rounded-2xl shadow-2xl backdrop-blur-xl z-50 py-2 custom-scrollbar">
                <div className="px-3 py-2 text-xs font-semibold text-zinc-500 uppercase tracking-wider">Select Report Date</div>
                {availableDates.map(date => (
                  <button
                    key={date}
                    onClick={() => {
                      setSelectedDate(date);
                      setIsHistoryOpen(false);
                    }}
                    className={`w-full text-left px-4 py-2.5 text-sm transition-colors flex items-center justify-between ${
                      selectedDate === date 
                        ? 'bg-emerald-500/10 text-emerald-400' 
                        : 'text-zinc-300 hover:bg-white/5'
                    }`}
                  >
                    <span>{formatDateDisplay(date)}</span>
                    {selectedDate === date && <div className="w-1.5 h-1.5 rounded-full bg-emerald-400"></div>}
                  </button>
                ))}

                {/* Option to create new if today isn't in list */}
                {!reports[getTodayString()] && (
                   <button
                   onClick={() => {
                     setSelectedDate(getTodayString());
                     setIsHistoryOpen(false);
                     setIsModalOpen(true);
                   }}
                   className="w-full text-left px-4 py-2.5 text-sm text-zinc-400 hover:text-white hover:bg-white/5 border-t border-white/5 mt-1"
                 >
                   + Create for Today
                 </button>
                )}
              </div>
            </>
          )}
        </div>

        {/* Add Report Button */}
        <button 
          onClick={() => setIsModalOpen(true)}
          className="group flex items-center gap-2 px-4 py-2.5 rounded-full bg-emerald-500/10 border border-emerald-500/20 hover:bg-emerald-500/20 hover:border-emerald-500/30 hover:scale-105 transition-all duration-300 backdrop-blur-md shadow-[0_0_20px_rgba(16,185,129,0.1)]"
        >
          <span className="p-1 rounded-full bg-emerald-500/20 group-hover:bg-emerald-500/30 transition-colors">
            <Plus size={16} className="text-emerald-400" />
          </span>
          <span className="text-sm font-medium text-emerald-100 pr-1">Add Report</span>
        </button>
      </div>

      {/* Main Report Container */}
      <div 
        ref={reportRef}
        data-report-container="true"
        className="relative z-10 w-full max-w-[1600px] mx-auto space-y-8 mt-12"
      >

        {/* TOP SECTION: P&L Calculator */}
        <div className="group relative rounded-3xl border border-white/5 bg-white/5 p-6 md:p-10 shadow-2xl backdrop-blur-2xl overflow-x-auto transition-all hover:bg-white/[0.07]">

           {/* Glossy sheen */}
           <div className="absolute inset-0 rounded-3xl bg-gradient-to-tr from-white/5 via-transparent to-transparent pointer-events-none"></div>

           {/* Header */}
          <div className="mb-8 border-b border-white/10 pb-4 min-w-[800px] flex items-center justify-between">
            <h1 className="text-2xl font-light text-white tracking-tight flex items-center gap-3">
                <div className="p-2 rounded-lg bg-white/5 border border-white/10 backdrop-blur-md shadow-inner">
                  <Activity size={20} className="text-zinc-300" />
                </div>
                Operations P&L
            </h1>
            <div className="text-xs font-mono text-zinc-500 border border-white/5 rounded-full px-3 py-1 bg-black/20 flex items-center gap-2">
               <Calendar size={12} />
               {formatDateDisplay(currentData.date)}
            </div>
          </div>

          {/* Equation Row */}
          <div className="flex flex-row items-stretch justify-between gap-3 min-w-[1000px] pb-2">

            <div className="flex-1">
              <MetricCard 
                label="Gross Sales" 
                amount={currentData.sales} 
                icon={Wallet}
                iconColor="text-zinc-300"
                accentColor="bg-zinc-200" 
              />
            </div>

            <Operator symbol="-" />

            <div className="flex-1">
              <MetricCard 
                label="Fees" 
                amount={currentData.sellingFee} 
                icon={CreditCard}
                iconColor="text-zinc-400"
                accentColor="bg-zinc-500"
              />
            </div>

            <Operator symbol="-" />

            <div className="flex-1">
              <MetricCard 
                label="COGS" 
                amount={currentData.cogs} 
                icon={Archive}
                iconColor="text-zinc-400"
                accentColor="bg-zinc-500"
              />
            </div>

            <Operator symbol="-" />

            <div className="flex-1">
              <MetricCard 
                label="Shipping" 
                amount={currentData.shipping} 
                icon={Truck}
                iconColor="text-zinc-400"
                accentColor="bg-zinc-500"
                subItems={getShippingBreakdown(currentData.shippingBreakdown)}
              />
            </div>

            <Operator symbol="=" />

            <div className="flex-1 transform transition-transform hover:scale-105">
               <MetricCard 
                 label="Net Profit" 
                 amount={profit} 
                 icon={TrendingUp}
                 iconColor={profit >= 0 ? "text-emerald-300" : "text-rose-300"}
                 accentColor={profit >= 0 ? "bg-emerald-400" : "bg-rose-400"}
                 textColor={profit >= 0 ? "text-emerald-200 drop-shadow-[0_0_10px_rgba(52,211,153,0.3)]" : "text-rose-200 drop-shadow-[0_0_10px_rgba(251,113,133,0.3)]"}
               />
            </div>

          </div>
        </div>

        {/* BOTTOM SECTION: Split View */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">

          {/* Daily Expenditure Panel */}
          <div className="relative rounded-3xl border border-white/5 bg-white/5 p-6 md:p-8 flex flex-col h-full backdrop-blur-2xl shadow-xl transition-all hover:bg-white/[0.07]">
            <div className="absolute inset-0 rounded-3xl bg-gradient-to-br from-white/5 to-transparent pointer-events-none"></div>

            <div className="relative z-10 flex items-center gap-3 mb-6 pb-4 border-b border-white/10">
              <div className="p-2 bg-rose-500/10 rounded-xl border border-rose-500/20 text-rose-300 shadow-[0_0_15px_rgba(244,63,94,0.1)]">
                <PieChart size={20} />
              </div>
              <h2 className="text-xl font-light text-zinc-100">Daily Expenditure</h2>
            </div>

            <div className="relative z-10 space-y-4 flex-1">
              <MetricCard 
                label="Investment" 
                amount={currentData.dailyInvestment} 
                icon={Wallet}
                iconColor="text-rose-300/80"
                accentColor="bg-rose-500" 
              />
              <MetricCard 
                label="Shipping" 
                amount={currentData.shipping} 
                icon={Truck}
                iconColor="text-rose-300/80"
                accentColor="bg-rose-500" 
                subItems={getShippingBreakdown(currentData.shippingBreakdown)}
              />
            </div>
             <div className="relative z-10 mt-6 pt-4 border-t border-white/10 flex justify-between items-center text-rose-200/80">
                <span className="text-xs font-mono uppercase tracking-wider">Total Outflow</span>
                <span className="text-xl font-light tabular-nums drop-shadow-lg">
                   {new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(totalDailyExpenditure)}
                </span>
             </div>
          </div>

          {/* Daily Earning Panel */}
          <div className="relative rounded-3xl border border-white/5 bg-white/5 p-6 md:p-8 flex flex-col h-full backdrop-blur-2xl shadow-xl transition-all hover:bg-white/[0.07]">
             <div className="absolute inset-0 rounded-3xl bg-gradient-to-br from-white/5 to-transparent pointer-events-none"></div>

            <div className="relative z-10 flex items-center gap-3 mb-6 pb-4 border-b border-white/10">
              <div className="p-2 bg-emerald-500/10 rounded-xl border border-emerald-500/20 text-emerald-300 shadow-[0_0_15px_rgba(16,185,129,0.1)]">
                <Calendar size={20} />
              </div>
              <h2 className="text-xl font-light text-zinc-100">Daily Earning</h2>
            </div>

            <div className="relative z-10 space-y-4 flex-1">
              <MetricCard 
                label="Expected Daily Earning" 
                amount={currentData.expectedDailyEarning} 
                icon={TrendingUp}
                iconColor="text-emerald-300/80"
                accentColor="bg-emerald-500" 
              />
              <MetricCard 
                label="Expected Weekly Payout" 
                amount={currentData.expectedWeeklyPayout} 
                icon={DollarSign}
                iconColor="text-emerald-300/80"
                accentColor="bg-emerald-500" 
              />
            </div>
             <div className="relative z-10 mt-6 pt-4 border-t border-white/10 flex justify-between items-center text-emerald-200/80">
                <span className="text-xs font-mono uppercase tracking-wider">Previous Week's Payout</span>
                <span className="text-xl font-light tabular-nums drop-shadow-lg">
                   {new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(currentData.previousWeeksPayout)}
                </span>
             </div>
          </div>

        </div>

        {/* Footer */}
        <div className="flex justify-between items-center px-4 py-6 border-t border-white/5">
           <div></div>
           <div className="flex gap-2 opacity-50">
             <div className="w-1.5 h-1.5 rounded-full bg-white/50"></div>
             <div className="w-1.5 h-1.5 rounded-full bg-white/30"></div>
             <div className="w-1.5 h-1.5 rounded-full bg-white/10"></div>
           </div>
        </div>

      </div>

      <AddReportModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveReport}
        initialData={currentData}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { LucideIcon } from 'lucide-react';

export interface SubItem {
  icon?: LucideIcon;
  label: string;
  amount: number;
}

interface MetricCardProps {
  label: string;
  amount: number;
  icon: LucideIcon;
  iconColor: string;
  accentColor: string;
  textColor?: string;
  subItems?: SubItem[];
}

export const MetricCard: React.FC<MetricCardProps> = ({
  label,
  amount,
  icon: Icon,
  iconColor,
  accentColor,
  textColor,
  subItems
}) => {

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(val);
  };

  return (
    <div className={`group relative w-full min-h-[5rem] md:min-h-[7rem] flex flex-col justify-between overflow-hidden rounded-xl md:rounded-2xl border border-white/5 bg-white/5 p-4 md:p-5 backdrop-blur-2xl transition-all duration-300 hover:border-white/10 hover:bg-white/10 hover:shadow-lg hover:shadow-black/20`}>

      {/* Glossy top reflection */}
      <div className="absolute inset-x-0 top-0 h-px bg-gradient-to-r from-transparent via-white/20 to-transparent opacity-50"></div>

      {/* Subtle indicator bar on left - glowing */}
      <div className={`absolute left-0 top-3 bottom-3 md:top-4 md:bottom-4 w-0.5 rounded-r-full opacity-80 shadow-[0_0_10px_currentColor] ${accentColor.replace('bg-', 'text-') /* Hack to reuse color class for shadow if needed, but accentColor is bg class usually. Let's just use the bg class provided */ } ${accentColor}`}></div>

      <div className="flex items-center justify-between mb-1.5 md:mb-2 relative z-10">
        <div className="flex items-center gap-2">
          <div className={`${iconColor} opacity-90 drop-shadow-[0_0_8px_rgba(255,255,255,0.2)]`}>
            <Icon size={14} className="md:w-4 md:h-4" strokeWidth={2} />
          </div>
          <p className="text-[10px] md:text-[11px] font-bold text-zinc-400 uppercase tracking-widest truncate select-none">{label}</p>
        </div>
      </div>

      <div className="relative z-10 flex flex-col justify-end flex-1">
          <h3 
            className={`text-xl md:text-2xl lg:text-3xl font-light tracking-tight tabular-nums select-none truncate w-full drop-shadow-sm ${textColor ? textColor : 'text-zinc-100'}`}
            title={formatCurrency(amount)}
          >
            {formatCurrency(amount)}
          </h3>

          {subItems && (
            <div className="mt-2 md:mt-3 pt-2 border-t border-white/5 space-y-1 animate-in fade-in slide-in-from-top-1 duration-300">
              {subItems.map((item, index) => (
                <div key={index} className="flex items-center justify-between text-[10px] text-zinc-400/80">
                  <div className="flex items-center gap-1.5">
                    {item.icon && <item.icon size={10} className="text-zinc-500" />}
                    <span className="font-medium tracking-wide">{item.label}</span>
                  </div>
                  <span className="font-mono text-zinc-300">{formatCurrency(item.amount)}</span>
                </div>
              ))}
            </div>
          )}
      </div>
    </div>
  );
};

import React, { useState, useRef, useMemo, useEffect } from 'react';
import { 
  DollarSign,
  TrendingUp,
  Wallet,
  CreditCard,
  Archive,
  Truck,
  PieChart,
  Activity,
  Calendar,
  Plus,
  ChevronDown,
  History,
  Copy,
  Check
} from 'lucide-react';
import { MetricCard, SubItem } from './components/MetricCard';
import { Orb } from './components/Orb';
import { AddReportModal } from './components/AddReportModal';
import { FinancialData, ShippingBreakdown } from './types';
import { db } from './firebase';
import { collection, doc, setDoc, getDocs, getDoc, serverTimestamp } from 'firebase/firestore';
import html2canvas from 'html2canvas';

// Noise SVG data URI for grain effect
const NOISE_SVG = `data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)' opacity='0.05'/%3E%3C/svg%3E`;

const Operator: React.FC<{ symbol: string; className?: string }> = ({ symbol, className = "" }) => (
  <div className={`flex items-center justify-center shrink-0 text-white/30 text-2xl md:text-4xl font-thin select-none drop-shadow-[0_0_5px_rgba(255,255,255,0.1)] ${className}`}>
    {symbol}
  </div>
);

// Helper to get today's date string YYYY-MM-DD
const getTodayString = () => new Date().toISOString().split('T')[0];

const App: React.FC = () => {
  // Store reports indexed by date string (YYYY-MM-DD)
  const [reports, setReports] = useState<Record<string, FinancialData>>({});

  // State for which date is currently selected
  const [selectedDate, setSelectedDate] = useState<string>(getTodayString());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [isCopying, setIsCopying] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);

  // Fetch all data from Firebase on mount to populate history
  useEffect(() => {
    const fetchAllData = async () => {
      try {
        const querySnapshot = await getDocs(collection(db, "dailyReports"));
        const fetchedReports: Record<string, FinancialData> = {};

        querySnapshot.forEach((doc) => {
          const data = doc.data();
          fetchedReports[doc.id] = {
            date: data.date,
            sales: data.sales,
            sellingFee: data.sellingFee,
            cogs: data.cogs,
            shipping: data.shipping,
            dailyInvestment: data.dailyInvestment,
            expectedDailyEarning: data.expectedDailyEarning,
            expectedWeeklyPayout: data.expectedWeeklyPayout,
            previousWeeksPayout: data.previousWeeksPayout,
            shippingBreakdown: data.shippingBreakdown
          } as FinancialData;
        });

        if (Object.keys(fetchedReports).length > 0) {
          setReports(prev => ({ ...prev, ...fetchedReports }));

          const today = getTodayString();
          if (fetchedReports[today]) {
             setSelectedDate(today);
          }
        }
      } catch (error) {
        console.error("Error fetching history: ", error);
      }
    };

    fetchAllData();
  }, []);

  // Fetch specific document when selectedDate changes
  useEffect(() => {
    const fetchSelectedReport = async () => {
      if (!selectedDate) return;

      try {
        const docRef = doc(db, "dailyReports", selectedDate);
        const docSnap = await getDoc(docRef);

        if (docSnap.exists()) {
          const data = docSnap.data();
          const loadedData = {
            date: data.date,
            sales: data.sales,
            sellingFee: data.sellingFee,
            cogs: data.cogs,
            shipping: data.shipping,
            dailyInvestment: data.dailyInvestment,
            expectedDailyEarning: data.expectedDailyEarning,
            expectedWeeklyPayout: data.expectedWeeklyPayout,
            previousWeeksPayout: data.previousWeeksPayout,
            shippingBreakdown: data.shippingBreakdown
          } as FinancialData;

          setReports(prev => ({
            ...prev,
            [selectedDate]: loadedData
          }));
          console.log("Loaded successfully");
        } else {
          console.log("No data found for date");
        }
      } catch (error) {
        console.error("Error loading report:", error);
      }
    };

    fetchSelectedReport();
  }, [selectedDate]);

  const availableDates = useMemo(() => {
    return Object.keys(reports).sort((a, b) => new Date(b).getTime() - new Date(a).getTime());
  }, [reports]);

  const currentData = useMemo(() => {
    return reports[selectedDate] || {
      date: selectedDate,
      sales: 0,
      sellingFee: 0,
      cogs: 0,
      shipping: 0,
      dailyInvestment: 0,
      expectedDailyEarning: 0,
      expectedWeeklyPayout: 0,
      previousWeeksPayout: 0,
      shippingBreakdown: { cards: [], balance: 0 }
    };
  }, [reports, selectedDate]);

  const profit = currentData.sales - (currentData.sellingFee + currentData.cogs + currentData.shipping);
  const totalDailyExpenditure = currentData.dailyInvestment + currentData.shipping;

  const reportRef = useRef<HTMLDivElement>(null);

  const handleSaveReport = async (newData: FinancialData) => {
    setReports(prev => ({
      ...prev,
      [newData.date]: newData
    }));
    setSelectedDate(newData.date);

    try {
      await setDoc(doc(db, "dailyReports", newData.date), {
        ...newData,
        createdAt: serverTimestamp()
      });
      console.log("Saved successfully");
    } catch (error) {
      console.error("Error saving document: ", error);
      alert("Failed to save report. Please check your connection.");
    }
  };

  const handleCopyReport = async () => {
    if (!reportRef.current || isCopying) return;

    setIsCopying(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 100));

      const canvas = await html2canvas(reportRef.current, {
        backgroundColor: '#09090b',
        scale: 2,
        logging: false,
        useCORS: true,
        allowTaint: true,
        onclone: (clonedDoc) => {
          const element = clonedDoc.querySelector('[data-report-container]') as HTMLElement;
          if (element) {
            element.style.padding = "20px";
            element.style.borderRadius = "24px";
            // Ensure container width is fixed for screenshot to prevent mobile stacking layout in the image if desired, 
            // or let it be responsive. Letting it be responsive matches what the user sees.
          }
        }
      });

      canvas.toBlob(async (blob) => {
        if (!blob) {
            console.error("Canvas to blob failed");
            return;
        }

        try {
          await navigator.clipboard.write([
            new ClipboardItem({
              [blob.type]: blob
            })
          ]);
          setCopySuccess(true);
          setTimeout(() => setCopySuccess(false), 2000);
        } catch (err) {
          console.error("Clipboard write failed", err);
          alert("Could not copy image to clipboard. Browser may not support it.");
        }
      }, 'image/png');
    } catch (err) {
      console.error("Screenshot failed", err);
      alert("Failed to generate screenshot.");
    } finally {
      setIsCopying(false);
    }
  };

  const getShippingBreakdown = (breakdown: ShippingBreakdown): SubItem[] => {
    const cardItems = breakdown?.cards?.map(card => ({
      icon: CreditCard,
      label: `Card •• ${card.last4}`,
      amount: card.amount
    })) || [];

    if (breakdown?.balance) {
      cardItems.push({ icon: Wallet, label: 'Seller Balance', amount: breakdown.balance });
    }

    return cardItems;
  };

  const formatDateDisplay = (dateStr: string) => {
    const date = new Date(dateStr);
    return new Intl.DateTimeFormat('en-US', { month: 'long', day: 'numeric', year: 'numeric' }).format(date);
  };

  return (
    <div className="min-h-screen bg-black text-zinc-100 flex flex-col items-center justify-start p-4 md:p-8 relative selection:bg-cyan-500/30 overflow-x-hidden font-sans pb-20">

      {/* Noise Texture Overlay */}
      <div 
        className="fixed inset-0 z-[1] pointer-events-none mix-blend-overlay opacity-30"
        style={{ backgroundImage: `url("${NOISE_SVG}")` }}
      ></div>

      {/* Background Gradients */}
      <div className="fixed inset-0 z-0 pointer-events-none bg-[radial-gradient(circle_at_50%_50%,_rgba(20,20,30,1),_rgba(0,0,0,1))]"></div>

      {/* Decorative Orbs - Reduced size/opacity on mobile via CSS classes could be added if needed, but keeping standard */}
      <Orb hue={280} size={900} speed={0.004} className="top-[-30%] left-[-20%] md:top-[-40%] md:left-[-20%] animate-pulse-slow" />
      <Orb hue={180} size={800} speed={0.006} className="bottom-[-30%] right-[-20%] md:bottom-[-40%] md:right-[-20%]" />
      <Orb hue={320} size={400} speed={0.008} className="top-[20%] right-[10%] opacity-40" />

      {/* Responsive Header */}
      <header className="w-full max-w-[1600px] mx-auto z-50 flex flex-col md:flex-row justify-between items-center gap-4 mb-6 md:mb-12 pt-2 md:pt-0">

        {/* Logo */}
        <div className="flex-shrink-0">
          <img 
            src="https://app.kambojventures.com/assets/images/logos/logo.png" 
            alt="Kamboj Ventures" 
            className="h-10 md:h-12 w-auto drop-shadow-lg opacity-90 hover:opacity-100 transition-opacity"
          />
        </div>

        {/* Controls */}
        <div className="flex items-center gap-2 md:gap-3 flex-wrap justify-center md:justify-end w-full md:w-auto">

          {/* Copy Button */}
          <button
            onClick={handleCopyReport}
            disabled={isCopying}
            className={`flex items-center gap-2 px-3 md:px-4 py-2 md:py-2.5 rounded-full border transition-all duration-300 backdrop-blur-md ${
              copySuccess 
                ? 'bg-emerald-500/20 border-emerald-500/30 text-emerald-300' 
                : 'bg-white/5 border-white/10 hover:bg-white/10 text-zinc-300 hover:text-white'
            }`}
          >
            {copySuccess ? <Check size={14} className="md:w-4 md:h-4" /> : <Copy size={14} className="md:w-4 md:h-4" />}
            <span className="text-xs md:text-sm font-medium">
              {isCopying ? 'Copying...' : copySuccess ? 'Copied' : 'Copy'}
            </span>
          </button>

          {/* Date Selector */}
          <div className="relative">
            <button 
              onClick={() => setIsHistoryOpen(!isHistoryOpen)}
              className="flex items-center gap-2 px-3 md:px-4 py-2 md:py-2.5 rounded-full bg-white/5 border border-white/10 hover:bg-white/10 transition-all backdrop-blur-md"
            >
              <History size={14} className="text-zinc-400 md:w-4 md:h-4" />
              <span className="text-xs md:text-sm font-medium text-zinc-200">{formatDateDisplay(selectedDate)}</span>
              <ChevronDown size={12} className={`text-zinc-500 transition-transform md:w-3.5 md:h-3.5 ${isHistoryOpen ? 'rotate-180' : ''}`} />
            </button>

            {isHistoryOpen && (
              <>
                <div className="fixed inset-0 z-40" onClick={() => setIsHistoryOpen(false)}></div>
                <div className="absolute top-full right-0 mt-2 w-56 max-h-64 overflow-y-auto bg-zinc-900/95 border border-white/10 rounded-2xl shadow-2xl backdrop-blur-xl z-50 py-2 custom-scrollbar">
                  <div className="px-3 py-2 text-xs font-semibold text-zinc-500 uppercase tracking-wider">Select Report Date</div>
                  {availableDates.map(date => (
                    <button
                      key={date}
                      onClick={() => {
                        setSelectedDate(date);
                        setIsHistoryOpen(false);
                      }}
                      className={`w-full text-left px-4 py-2.5 text-sm transition-colors flex items-center justify-between ${
                        selectedDate === date 
                          ? 'bg-emerald-500/10 text-emerald-400' 
                          : 'text-zinc-300 hover:bg-white/5'
                      }`}
                    >
                      <span>{formatDateDisplay(date)}</span>
                      {selectedDate === date && <div className="w-1.5 h-1.5 rounded-full bg-emerald-400"></div>}
                    </button>
                  ))}
                  {!reports[getTodayString()] && (
                     <button
                     onClick={() => {
                       setSelectedDate(getTodayString());
                       setIsHistoryOpen(false);
                       setIsModalOpen(true);
                     }}
                     className="w-full text-left px-4 py-2.5 text-sm text-zinc-400 hover:text-white hover:bg-white/5 border-t border-white/5 mt-1"
                   >
                     + Create for Today
                   </button>
                  )}
                </div>
              </>
            )}
          </div>

          {/* Add Report Button */}
          <button 
            onClick={() => setIsModalOpen(true)}
            className="group flex items-center gap-2 px-3 md:px-4 py-2 md:py-2.5 rounded-full bg-emerald-500/10 border border-emerald-500/20 hover:bg-emerald-500/20 hover:border-emerald-500/30 hover:scale-105 transition-all duration-300 backdrop-blur-md shadow-[0_0_20px_rgba(16,185,129,0.1)]"
          >
            <span className="p-0.5 md:p-1 rounded-full bg-emerald-500/20 group-hover:bg-emerald-500/30 transition-colors">
              <Plus size={14} className="text-emerald-400 md:w-4 md:h-4" />
            </span>
            <span className="text-xs md:text-sm font-medium text-emerald-100 pr-1">Add Report</span>
          </button>
        </div>
      </header>

      {/* Main Report Container */}
      <div 
        ref={reportRef}
        data-report-container="true"
        className="relative z-10 w-full max-w-[1600px] mx-auto space-y-4 md:space-y-8"
      >

        {/* TOP SECTION: P&L Calculator */}
        {/* Mobile: Vertical Stack / Desktop: Horizontal Row */}
        <div className="group relative rounded-2xl md:rounded-3xl border border-white/5 bg-white/5 p-4 md:p-10 shadow-2xl backdrop-blur-2xl transition-all hover:bg-white/[0.07]">

           {/* Glossy sheen */}
           <div className="absolute inset-0 rounded-2xl md:rounded-3xl bg-gradient-to-tr from-white/5 via-transparent to-transparent pointer-events-none"></div>

           {/* Header */}
          <div className="mb-4 md:mb-8 border-b border-white/10 pb-3 md:pb-4 flex flex-col md:flex-row md:items-center justify-between gap-2 md:gap-0">
            <h1 className="text-lg md:text-2xl font-light text-white tracking-tight flex items-center gap-2 md:gap-3">
                <div className="p-1.5 md:p-2 rounded-lg bg-white/5 border border-white/10 backdrop-blur-md shadow-inner">
                  <Activity size={16} className="text-zinc-300 md:w-5 md:h-5" />
                </div>
                Operations P&L
            </h1>
            <div className="self-start md:self-auto text-[10px] md:text-xs font-mono text-zinc-500 border border-white/5 rounded-full px-2 md:px-3 py-1 bg-black/20 flex items-center gap-1.5 md:gap-2">
               <Calendar size={10} className="md:w-3 md:h-3" />
               {formatDateDisplay(currentData.date)}
            </div>
          </div>

          {/* P&L Flow */}
          <div className="flex flex-col md:flex-row items-stretch justify-between gap-2 md:gap-3">

            <div className="flex-1">
              <MetricCard 
                label="Gross Sales" 
                amount={currentData.sales} 
                icon={Wallet}
                iconColor="text-zinc-300"
                accentColor="bg-zinc-200" 
              />
            </div>

            <Operator symbol="-" className="hidden md:flex" />

            <div className="flex-1">
              <MetricCard 
                label="Fees" 
                amount={currentData.sellingFee} 
                icon={CreditCard}
                iconColor="text-zinc-400"
                accentColor="bg-zinc-500"
              />
            </div>

            {/* Mobile Operator */}
            <div className="flex md:hidden justify-center -my-1 relative z-0 opacity-50"><Operator symbol="-" className="text-lg" /></div>

            <Operator symbol="-" className="hidden md:flex" />

            <div className="flex-1">
              <MetricCard 
                label="COGS" 
                amount={currentData.cogs} 
                icon={Archive}
                iconColor="text-zinc-400"
                accentColor="bg-zinc-500"
              />
            </div>

            <div className="flex md:hidden justify-center -my-1 relative z-0 opacity-50"><Operator symbol="-" className="text-lg" /></div>

            <Operator symbol="-" className="hidden md:flex" />

            <div className="flex-1">
              <MetricCard 
                label="Shipping" 
                amount={currentData.shipping} 
                icon={Truck}
                iconColor="text-zinc-400"
                accentColor="bg-zinc-500"
                subItems={getShippingBreakdown(currentData.shippingBreakdown)}
              />
            </div>

            <div className="flex md:hidden justify-center -my-1 relative z-0 opacity-50"><Operator symbol="=" className="text-lg" /></div>

            <Operator symbol="=" className="hidden md:flex" />

            <div className="flex-1 transform transition-transform hover:scale-[1.02] md:hover:scale-105">
               <MetricCard 
                 label="Net Profit" 
                 amount={profit} 
                 icon={TrendingUp}
                 iconColor={profit >= 0 ? "text-emerald-300" : "text-rose-300"}
                 accentColor={profit >= 0 ? "bg-emerald-400" : "bg-rose-400"}
                 textColor={profit >= 0 ? "text-emerald-200 drop-shadow-[0_0_10px_rgba(52,211,153,0.3)]" : "text-rose-200 drop-shadow-[0_0_10px_rgba(251,113,133,0.3)]"}
               />
            </div>

          </div>
        </div>

        {/* BOTTOM SECTION: Split View */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-8">

          {/* Daily Expenditure Panel */}
          <div className="relative rounded-2xl md:rounded-3xl border border-white/5 bg-white/5 p-4 md:p-8 flex flex-col h-full backdrop-blur-2xl shadow-xl transition-all hover:bg-white/[0.07]">
            <div className="absolute inset-0 rounded-2xl md:rounded-3xl bg-gradient-to-br from-white/5 to-transparent pointer-events-none"></div>

            <div className="relative z-10 flex items-center gap-2 md:gap-3 mb-4 md:mb-6 pb-3 md:pb-4 border-b border-white/10">
              <div className="p-1.5 md:p-2 bg-rose-500/10 rounded-xl border border-rose-500/20 text-rose-300 shadow-[0_0_15px_rgba(244,63,94,0.1)]">
                <PieChart size={16} className="md:w-5 md:h-5" />
              </div>
              <h2 className="text-lg md:text-xl font-light text-zinc-100">Daily Expenditure</h2>
            </div>

            <div className="relative z-10 space-y-3 md:space-y-4 flex-1">
              <MetricCard 
                label="Investment" 
                amount={currentData.dailyInvestment} 
                icon={Wallet}
                iconColor="text-rose-300/80"
                accentColor="bg-rose-500" 
              />
              <MetricCard 
                label="Shipping" 
                amount={currentData.shipping} 
                icon={Truck}
                iconColor="text-rose-300/80"
                accentColor="bg-rose-500" 
                subItems={getShippingBreakdown(currentData.shippingBreakdown)}
              />
            </div>
             <div className="relative z-10 mt-4 md:mt-6 pt-3 md:pt-4 border-t border-white/10 flex justify-between items-center text-rose-200/80">
                <span className="text-[10px] md:text-xs font-mono uppercase tracking-wider">Total Outflow</span>
                <span className="text-lg md:text-xl font-light tabular-nums drop-shadow-lg">
                   {new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(totalDailyExpenditure)}
                </span>
             </div>
          </div>

          {/* Daily Earning Panel */}
          <div className="relative rounded-2xl md:rounded-3xl border border-white/5 bg-white/5 p-4 md:p-8 flex flex-col h-full backdrop-blur-2xl shadow-xl transition-all hover:bg-white/[0.07]">
             <div className="absolute inset-0 rounded-2xl md:rounded-3xl bg-gradient-to-br from-white/5 to-transparent pointer-events-none"></div>

            <div className="relative z-10 flex items-center gap-2 md:gap-3 mb-4 md:mb-6 pb-3 md:pb-4 border-b border-white/10">
              <div className="p-1.5 md:p-2 bg-emerald-500/10 rounded-xl border border-emerald-500/20 text-emerald-300 shadow-[0_0_15px_rgba(16,185,129,0.1)]">
                <Calendar size={16} className="md:w-5 md:h-5" />
              </div>
              <h2 className="text-lg md:text-xl font-light text-zinc-100">Daily Earning</h2>
            </div>

            <div className="relative z-10 space-y-3 md:space-y-4 flex-1">
              <MetricCard 
                label="Expected Daily Earning" 
                amount={currentData.expectedDailyEarning} 
                icon={TrendingUp}
                iconColor="text-emerald-300/80"
                accentColor="bg-emerald-500" 
              />
              <MetricCard 
                label="Expected Weekly Payout" 
                amount={currentData.expectedWeeklyPayout} 
                icon={DollarSign}
                iconColor="text-emerald-300/80"
                accentColor="bg-emerald-500" 
              />
            </div>
             <div className="relative z-10 mt-4 md:mt-6 pt-3 md:pt-4 border-t border-white/10 flex justify-between items-center text-emerald-200/80">
                <span className="text-[10px] md:text-xs font-mono uppercase tracking-wider">Previous Week's Payout</span>
                <span className="text-lg md:text-xl font-light tabular-nums drop-shadow-lg">
                   {new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(currentData.previousWeeksPayout)}
                </span>
             </div>
          </div>

        </div>

        {/* Footer */}
        <div className="flex justify-between items-center px-4 py-6 border-t border-white/5">
           <div></div>
           <div className="flex gap-2 opacity-50">
             <div className="w-1.5 h-1.5 rounded-full bg-white/50"></div>
             <div className="w-1.5 h-1.5 rounded-full bg-white/30"></div>
             <div className="w-1.5 h-1.5 rounded-full bg-white/10"></div>
           </div>
        </div>

      </div>

      <AddReportModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveReport}
        initialData={currentData}
      />
    </div>
  );
};

export default App;

import React, { useState, useRef, useMemo, useEffect } from 'react';
import { 
  DollarSign,
  TrendingUp,
  Wallet,
  CreditCard,
  Archive,
  Truck,
  PieChart,
  Activity,
  Calendar,
  Plus,
  ChevronDown,
  History,
  Copy,
  Check
} from 'lucide-react';
import { MetricCard, SubItem } from './components/MetricCard';
import { Orb } from './components/Orb';
import { AddReportModal } from './components/AddReportModal';
import { FinancialData, ShippingBreakdown } from './types';
import { db } from './firebase';
import { collection, doc, setDoc, getDocs, getDoc, serverTimestamp } from 'firebase/firestore';
import html2canvas from 'html2canvas';

// Noise SVG data URI for grain effect
const NOISE_SVG = `data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)' opacity='0.05'/%3E%3C/svg%3E`;

const Operator: React.FC<{ symbol: string; className?: string }> = ({ symbol, className = "" }) => (
  <div className={`flex items-center justify-center shrink-0 text-white/30 text-2xl md:text-4xl font-thin select-none drop-shadow-[0_0_5px_rgba(255,255,255,0.1)] ${className}`}>
    {symbol}
  </div>
);

// Helper to get today's date string YYYY-MM-DD
const getTodayString = () => new Date().toISOString().split('T')[0];

const App: React.FC = () => {
  // Store reports indexed by date string (YYYY-MM-DD)
  const [reports, setReports] = useState<Record<string, FinancialData>>({});

  // State for which date is currently selected
  const [selectedDate, setSelectedDate] = useState<string>(getTodayString());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [isCopying, setIsCopying] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);

  // Fetch all data from Firebase on mount to populate history
  useEffect(() => {
    const fetchAllData = async () => {
      try {
        const querySnapshot = await getDocs(collection(db, "dailyReports"));
        const fetchedReports: Record<string, FinancialData> = {};

        querySnapshot.forEach((doc) => {
          const data = doc.data();
          fetchedReports[doc.id] = {
            date: data.date,
            sales: data.sales,
            sellingFee: data.sellingFee,
            cogs: data.cogs,
            shipping: data.shipping,
            dailyInvestment: data.dailyInvestment,
            expectedDailyEarning: data.expectedDailyEarning,
            expectedWeeklyPayout: data.expectedWeeklyPayout,
            previousWeeksPayout: data.previousWeeksPayout,
            shippingBreakdown: data.shippingBreakdown
          } as FinancialData;
        });

        const dateKeys = Object.keys(fetchedReports);
        if (dateKeys.length > 0) {
          setReports(prev => ({ ...prev, ...fetchedReports }));

          // Sort dates descending to find the latest saved report
          const sortedDates = dateKeys.sort((a, b) => new Date(b).getTime() - new Date(a).getTime());
          // Default to the most recent report available
          setSelectedDate(sortedDates[0]);
        }
      } catch (error) {
        console.error("Error fetching history: ", error);
      }
    };

    fetchAllData();
  }, []);

  // Fetch specific document when selectedDate changes
  useEffect(() => {
    const fetchSelectedReport = async () => {
      if (!selectedDate) return;

      try {
        const docRef = doc(db, "dailyReports", selectedDate);
        const docSnap = await getDoc(docRef);

        if (docSnap.exists()) {
          const data = docSnap.data();
          const loadedData = {
            date: data.date,
            sales: data.sales,
            sellingFee: data.sellingFee,
            cogs: data.cogs,
            shipping: data.shipping,
            dailyInvestment: data.dailyInvestment,
            expectedDailyEarning: data.expectedDailyEarning,
            expectedWeeklyPayout: data.expectedWeeklyPayout,
            previousWeeksPayout: data.previousWeeksPayout,
            shippingBreakdown: data.shippingBreakdown
          } as FinancialData;

          setReports(prev => ({
            ...prev,
            [selectedDate]: loadedData
          }));
          console.log("Loaded successfully");
        } else {
          console.log("No data found for date");
        }
      } catch (error) {
        console.error("Error loading report:", error);
      }
    };

    fetchSelectedReport();
  }, [selectedDate]);

  const availableDates = useMemo(() => {
    return Object.keys(reports).sort((a, b) => new Date(b).getTime() - new Date(a).getTime());
  }, [reports]);

  const currentData = useMemo(() => {
    return reports[selectedDate] || {
      date: selectedDate,
      sales: 0,
      sellingFee: 0,
      cogs: 0,
      shipping: 0,
      dailyInvestment: 0,
      expectedDailyEarning: 0,
      expectedWeeklyPayout: 0,
      previousWeeksPayout: 0,
      shippingBreakdown: { cards: [], balance: 0 }
    };
  }, [reports, selectedDate]);

  const profit = currentData.sales - (currentData.sellingFee + currentData.cogs + currentData.shipping);
  const totalDailyExpenditure = currentData.dailyInvestment + currentData.shipping;

  const reportRef = useRef<HTMLDivElement>(null);

  const handleSaveReport = async (newData: FinancialData) => {
    // Optimistic update
    setReports(prev => ({
      ...prev,
      [newData.date]: newData
    }));
    setSelectedDate(newData.date);

    try {
      await setDoc(doc(db, "dailyReports", newData.date), {
        ...newData,
        createdAt: serverTimestamp()
      });
      console.log("Saved successfully");
    } catch (error) {
      console.error("Error saving document: ", error);
      alert("Failed to save report. Please check your connection.");
      // Re-throw so modal knows it failed
      throw error;
    }
  };

  const handleCopyReport = async () => {
    if (!reportRef.current || isCopying) return;

    setIsCopying(true);
    try {
      await new Promise(resolve => setTimeout(resolve, 100));

      const canvas = await html2canvas(reportRef.current, {
        backgroundColor: '#09090b',
        scale: 2,
        logging: false,
        useCORS: true,
        allowTaint: true,
        onclone: (clonedDoc) => {
          const element = clonedDoc.querySelector('[data-report-container]') as HTMLElement;
          if (element) {
            element.style.padding = "20px";
            element.style.borderRadius = "24px";
            // Ensure container width is fixed for screenshot to prevent mobile stacking layout in the image if desired, 
            // or let it be responsive. Letting it be responsive matches what the user sees.
          }
        }
      });

      canvas.toBlob(async (blob) => {
        if (!blob) {
            console.error("Canvas to blob failed");
            return;
        }

        try {
          await navigator.clipboard.write([
            new ClipboardItem({
              [blob.type]: blob
            })
          ]);
          setCopySuccess(true);
          setTimeout(() => setCopySuccess(false), 2000);
        } catch (err) {
          console.error("Clipboard write failed", err);
          alert("Could not copy image to clipboard. Browser may not support it.");
        }
      }, 'image/png');
    } catch (err) {
      console.error("Screenshot failed", err);
      alert("Failed to generate screenshot.");
    } finally {
      setIsCopying(false);
    }
  };

  const getShippingBreakdown = (breakdown: ShippingBreakdown): SubItem[] => {
    const cardItems = breakdown?.cards?.map(card => ({
      icon: CreditCard,
      label: `Card •• ${card.last4}`,
      amount: card.amount
    })) || [];

    if (breakdown?.balance) {
      cardItems.push({ icon: Wallet, label: 'Seller Balance', amount: breakdown.balance });
    }

    return cardItems;
  };

  const formatDateDisplay = (dateStr: string) => {
    const date = new Date(dateStr);
    return new Intl.DateTimeFormat('en-US', { month: 'long', day: 'numeric', year: 'numeric' }).format(date);
  };

  return (
    <div className="min-h-screen bg-black text-zinc-100 flex flex-col items-center justify-start p-4 md:p-8 relative selection:bg-cyan-500/30 overflow-x-hidden font-sans pb-20">

      {/* Noise Texture Overlay */}
      <div 
        className="fixed inset-0 z-[1] pointer-events-none mix-blend-overlay opacity-30"
        style={{ backgroundImage: `url("${NOISE_SVG}")` }}
      ></div>

      {/* Background Gradients */}
      <div className="fixed inset-0 z-0 pointer-events-none bg-[radial-gradient(circle_at_50%_50%,_rgba(20,20,30,1),_rgba(0,0,0,1))]"></div>

      {/* Decorative Orbs - Reduced size/opacity on mobile via CSS classes could be added if needed, but keeping standard */}
      <Orb hue={280} size={900} speed={0.004} className="top-[-30%] left-[-20%] md:top-[-40%] md:left-[-20%] animate-pulse-slow" />
      <Orb hue={180} size={800} speed={0.006} className="bottom-[-30%] right-[-20%] md:bottom-[-40%] md:right-[-20%]" />
      <Orb hue={320} size={400} speed={0.008} className="top-[20%] right-[10%] opacity-40" />

      {/* Responsive Header */}
      <header className="w-full max-w-[1600px] mx-auto z-50 flex flex-col md:flex-row justify-between items-center gap-4 mb-6 md:mb-12 pt-2 md:pt-0">

        {/* Logo */}
        <div className="flex-shrink-0">
          <img 
            src="https://app.kambojventures.com/assets/images/logos/logo.png" 
            alt="Kamboj Ventures" 
            className="h-10 md:h-12 w-auto drop-shadow-lg opacity-90 hover:opacity-100 transition-opacity"
          />
        </div>

        {/* Controls */}
        <div className="flex items-center gap-2 md:gap-3 flex-wrap justify-center md:justify-end w-full md:w-auto">

          {/* Copy Button */}
          <button
            onClick={handleCopyReport}
            disabled={isCopying}
            className={`flex items-center gap-2 px-3 md:px-4 py-2 md:py-2.5 rounded-full border transition-all duration-300 backdrop-blur-md ${
              copySuccess 
                ? 'bg-emerald-500/20 border-emerald-500/30 text-emerald-300' 
                : 'bg-white/5 border-white/10 hover:bg-white/10 text-zinc-300 hover:text-white'
            }`}
          >
            {copySuccess ? <Check size={14} className="md:w-4 md:h-4" /> : <Copy size={14} className="md:w-4 md:h-4" />}
            <span className="text-xs md:text-sm font-medium">
              {isCopying ? 'Copying...' : copySuccess ? 'Copied' : 'Copy'}
            </span>
          </button>

          {/* Date Selector */}
          <div className="relative">
            <button 
              onClick={() => setIsHistoryOpen(!isHistoryOpen)}
              className="flex items-center gap-2 px-3 md:px-4 py-2 md:py-2.5 rounded-full bg-white/5 border border-white/10 hover:bg-white/10 transition-all backdrop-blur-md"
            >
              <History size={14} className="text-zinc-400 md:w-4 md:h-4" />
              <span className="text-xs md:text-sm font-medium text-zinc-200">{formatDateDisplay(selectedDate)}</span>
              <ChevronDown size={12} className={`text-zinc-500 transition-transform md:w-3.5 md:h-3.5 ${isHistoryOpen ? 'rotate-180' : ''}`} />
            </button>

            {isHistoryOpen && (
              <>
                <div className="fixed inset-0 z-40" onClick={() => setIsHistoryOpen(false)}></div>
                <div className="absolute top-full right-0 mt-2 w-56 max-h-64 overflow-y-auto bg-zinc-900/95 border border-white/10 rounded-2xl shadow-2xl backdrop-blur-xl z-50 py-2 custom-scrollbar">
                  <div className="px-3 py-2 text-xs font-semibold text-zinc-500 uppercase tracking-wider">Select Report Date</div>
                  {availableDates.map(date => (
                    <button
                      key={date}
                      onClick={() => {
                        setSelectedDate(date);
                        setIsHistoryOpen(false);
                      }}
                      className={`w-full text-left px-4 py-2.5 text-sm transition-colors flex items-center justify-between ${
                        selectedDate === date 
                          ? 'bg-emerald-500/10 text-emerald-400' 
                          : 'text-zinc-300 hover:bg-white/5'
                      }`}
                    >
                      <span>{formatDateDisplay(date)}</span>
                      {selectedDate === date && <div className="w-1.5 h-1.5 rounded-full bg-emerald-400"></div>}
                    </button>
                  ))}
                  {!reports[getTodayString()] && (
                     <button
                     onClick={() => {
                       setSelectedDate(getTodayString());
                       setIsHistoryOpen(false);
                       setIsModalOpen(true);
                     }}
                     className="w-full text-left px-4 py-2.5 text-sm text-zinc-400 hover:text-white hover:bg-white/5 border-t border-white/5 mt-1"
                   >
                     + Create for Today
                   </button>
                  )}
                </div>
              </>
            )}
          </div>

          {/* Add Report Button */}
          <button 
            onClick={() => setIsModalOpen(true)}
            className="group flex items-center gap-2 px-3 md:px-4 py-2 md:py-2.5 rounded-full bg-emerald-500/10 border border-emerald-500/20 hover:bg-emerald-500/20 hover:border-emerald-500/30 hover:scale-105 transition-all duration-300 backdrop-blur-md shadow-[0_0_20px_rgba(16,185,129,0.1)]"
          >
            <span className="p-0.5 md:p-1 rounded-full bg-emerald-500/20 group-hover:bg-emerald-500/30 transition-colors">
              <Plus size={14} className="text-emerald-400 md:w-4 md:h-4" />
            </span>
            <span className="text-xs md:text-sm font-medium text-emerald-100 pr-1">Add Report</span>
          </button>
        </div>
      </header>

      {/* Main Report Container */}
      <div 
        ref={reportRef}
        data-report-container="true"
        className="relative z-10 w-full max-w-[1600px] mx-auto space-y-4 md:space-y-8"
      >

        {/* TOP SECTION: P&L Calculator */}
        {/* Mobile: Vertical Stack / Desktop: Horizontal Row */}
        <div className="group relative rounded-2xl md:rounded-3xl border border-white/5 bg-white/5 p-4 md:p-10 shadow-2xl backdrop-blur-2xl transition-all hover:bg-white/[0.07]">

           {/* Glossy sheen */}
           <div className="absolute inset-0 rounded-2xl md:rounded-3xl bg-gradient-to-tr from-white/5 via-transparent to-transparent pointer-events-none"></div>

           {/* Header */}
          <div className="mb-4 md:mb-8 border-b border-white/10 pb-3 md:pb-4 flex flex-col md:flex-row md:items-center justify-between gap-2 md:gap-0">
            <h1 className="text-lg md:text-2xl font-light text-white tracking-tight flex items-center gap-2 md:gap-3">
                <div className="p-1.5 md:p-2 rounded-lg bg-white/5 border border-white/10 backdrop-blur-md shadow-inner">
                  <Activity size={16} className="text-zinc-300 md:w-5 md:h-5" />
                </div>
                Operations P&L
            </h1>
            <div className="self-start md:self-auto text-[10px] md:text-xs font-mono text-zinc-500 border border-white/5 rounded-full px-2 md:px-3 py-1 bg-black/20 flex items-center gap-1.5 md:gap-2">
               <Calendar size={10} className="md:w-3 md:h-3" />
               {formatDateDisplay(currentData.date)}
            </div>
          </div>

          {/* P&L Flow */}
          <div className="flex flex-col md:flex-row items-stretch justify-between gap-2 md:gap-3">

            <div className="flex-1">
              <MetricCard 
                label="Gross Sales" 
                amount={currentData.sales} 
                icon={Wallet}
                iconColor="text-zinc-300"
                accentColor="bg-zinc-200" 
              />
            </div>

            <Operator symbol="-" className="hidden md:flex" />

            <div className="flex-1">
              <MetricCard 
                label="Fees" 
                amount={currentData.sellingFee} 
                icon={CreditCard}
                iconColor="text-zinc-400"
                accentColor="bg-zinc-500"
              />
            </div>

            {/* Mobile Operator */}
            <div className="flex md:hidden justify-center -my-1 relative z-0 opacity-50"><Operator symbol="-" className="text-lg" /></div>

            <Operator symbol="-" className="hidden md:flex" />

            <div className="flex-1">
              <MetricCard 
                label="COGS" 
                amount={currentData.cogs} 
                icon={Archive}
                iconColor="text-zinc-400"
                accentColor="bg-zinc-500"
              />
            </div>

            <div className="flex md:hidden justify-center -my-1 relative z-0 opacity-50"><Operator symbol="-" className="text-lg" /></div>

            <Operator symbol="-" className="hidden md:flex" />

            <div className="flex-1">
              <MetricCard 
                label="Shipping" 
                amount={currentData.shipping} 
                icon={Truck}
                iconColor="text-zinc-400"
                accentColor="bg-zinc-500"
                subItems={getShippingBreakdown(currentData.shippingBreakdown)}
              />
            </div>

            <div className="flex md:hidden justify-center -my-1 relative z-0 opacity-50"><Operator symbol="=" className="text-lg" /></div>

            <Operator symbol="=" className="hidden md:flex" />

            <div className="flex-1 transform transition-transform hover:scale-[1.02] md:hover:scale-105">
               <MetricCard 
                 label="Net Profit" 
                 amount={profit} 
                 icon={TrendingUp}
                 iconColor={profit >= 0 ? "text-emerald-300" : "text-rose-300"}
                 accentColor={profit >= 0 ? "bg-emerald-400" : "bg-rose-400"}
                 textColor={profit >= 0 ? "text-emerald-200 drop-shadow-[0_0_10px_rgba(52,211,153,0.3)]" : "text-rose-200 drop-shadow-[0_0_10px_rgba(251,113,133,0.3)]"}
               />
            </div>

          </div>
        </div>

        {/* BOTTOM SECTION: Split View */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-8">

          {/* Daily Expenditure Panel */}
          <div className="relative rounded-2xl md:rounded-3xl border border-white/5 bg-white/5 p-4 md:p-8 flex flex-col h-full backdrop-blur-2xl shadow-xl transition-all hover:bg-white/[0.07]">
            <div className="absolute inset-0 rounded-2xl md:rounded-3xl bg-gradient-to-br from-white/5 to-transparent pointer-events-none"></div>

            <div className="relative z-10 flex items-center gap-2 md:gap-3 mb-4 md:mb-6 pb-3 md:pb-4 border-b border-white/10">
              <div className="p-1.5 md:p-2 bg-rose-500/10 rounded-xl border border-rose-500/20 text-rose-300 shadow-[0_0_15px_rgba(244,63,94,0.1)]">
                <PieChart size={16} className="md:w-5 md:h-5" />
              </div>
              <h2 className="text-lg md:text-xl font-light text-zinc-100">Daily Expenditure</h2>
            </div>

            <div className="relative z-10 space-y-3 md:space-y-4 flex-1">
              <MetricCard 
                label="Investment" 
                amount={currentData.dailyInvestment} 
                icon={Wallet}
                iconColor="text-rose-300/80"
                accentColor="bg-rose-500" 
              />
              <MetricCard 
                label="Shipping" 
                amount={currentData.shipping} 
                icon={Truck}
                iconColor="text-rose-300/80"
                accentColor="bg-rose-500" 
                subItems={getShippingBreakdown(currentData.shippingBreakdown)}
              />
            </div>
             <div className="relative z-10 mt-4 md:mt-6 pt-3 md:pt-4 border-t border-white/10 flex justify-between items-center text-rose-200/80">
                <span className="text-[10px] md:text-xs font-mono uppercase tracking-wider">Total Outflow</span>
                <span className="text-lg md:text-xl font-light tabular-nums drop-shadow-lg">
                   {new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(totalDailyExpenditure)}
                </span>
             </div>
          </div>

          {/* Daily Earning Panel */}
          <div className="relative rounded-2xl md:rounded-3xl border border-white/5 bg-white/5 p-4 md:p-8 flex flex-col h-full backdrop-blur-2xl shadow-xl transition-all hover:bg-white/[0.07]">
             <div className="absolute inset-0 rounded-2xl md:rounded-3xl bg-gradient-to-br from-white/5 to-transparent pointer-events-none"></div>

            <div className="relative z-10 flex items-center gap-2 md:gap-3 mb-4 md:mb-6 pb-3 md:pb-4 border-b border-white/10">
              <div className="p-1.5 md:p-2 bg-emerald-500/10 rounded-xl border border-emerald-500/20 text-emerald-300 shadow-[0_0_15px_rgba(16,185,129,0.1)]">
                <Calendar size={16} className="md:w-5 md:h-5" />
              </div>
              <h2 className="text-lg md:text-xl font-light text-zinc-100">Daily Earning</h2>
            </div>

            <div className="relative z-10 space-y-3 md:space-y-4 flex-1">
              <MetricCard 
                label="Expected Daily Earning" 
                amount={currentData.expectedDailyEarning} 
                icon={TrendingUp}
                iconColor="text-emerald-300/80"
                accentColor="bg-emerald-500" 
              />
              <MetricCard 
                label="Expected Weekly Payout" 
                amount={currentData.expectedWeeklyPayout} 
                icon={DollarSign}
                iconColor="text-emerald-300/80"
                accentColor="bg-emerald-500" 
              />
            </div>
             <div className="relative z-10 mt-4 md:mt-6 pt-3 md:pt-4 border-t border-white/10 flex justify-between items-center text-emerald-200/80">
                <span className="text-[10px] md:text-xs font-mono uppercase tracking-wider">Previous Week's Payout</span>
                <span className="text-lg md:text-xl font-light tabular-nums drop-shadow-lg">
                   {new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(currentData.previousWeeksPayout)}
                </span>
             </div>
          </div>

        </div>

        {/* Footer */}
        <div className="flex justify-between items-center px-4 py-6 border-t border-white/5">
           <div></div>
           <div className="flex gap-2 opacity-50">
             <div className="w-1.5 h-1.5 rounded-full bg-white/50"></div>
             <div className="w-1.5 h-1.5 rounded-full bg-white/30"></div>
             <div className="w-1.5 h-1.5 rounded-full bg-white/10"></div>
           </div>
        </div>

      </div>

      <AddReportModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveReport}
        initialData={currentData}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { X, Save, Wallet, CreditCard, LayoutDashboard, Plus, Trash2, Calendar, AlertTriangle } from 'lucide-react';
import { FinancialData, ShippingBreakdown } from '../types';

interface AddReportModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (data: FinancialData) => Promise<void>;
  initialData: FinancialData;
}

const LOCAL_STORAGE_KEY = 'kv_report_draft';

export const AddReportModal: React.FC<AddReportModalProps> = ({
  isOpen,
  onClose,
  onSave,
  initialData
}) => {
  const [formData, setFormData] = useState<FinancialData>(initialData);
  const [showConfirm, setShowConfirm] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // Load persistence on open
  useEffect(() => {
    if (isOpen) {
      const savedDraft = localStorage.getItem(LOCAL_STORAGE_KEY);
      if (savedDraft) {
        try {
          setFormData(JSON.parse(savedDraft));
        } catch (e) {
          console.error("Failed to parse draft", e);
          setFormData(initialData);
        }
      } else {
        setFormData(initialData);
      }
    }
  }, [isOpen, initialData]);

  // Persist changes
  useEffect(() => {
    if (isOpen) {
        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(formData));
    }
  }, [formData, isOpen]);

  const handleChange = (field: keyof FinancialData, value: string) => {
    setFormData(prev => ({
      ...prev,
      [field]: field === 'date' ? value : (parseFloat(value) || 0)
    }));
  };

  const handleShippingChange = (
    newBreakdown: ShippingBreakdown
  ) => {
    setFormData(prev => {
      // Calculate total for this specific breakdown
      const total = newBreakdown.cards.reduce((sum, c) => sum + c.amount, 0) + newBreakdown.balance;

      const updates: Partial<FinancialData> = { 
        shippingBreakdown: newBreakdown,
        shipping: total
      };

      return { ...prev, ...updates };
    });
  };

  const processSave = async () => {
    setIsSaving(true);
    try {
      await onSave(formData);
      // Only remove if successful
      localStorage.removeItem(LOCAL_STORAGE_KEY);
      onClose();
    } catch (e) {
      console.error("Save failed in modal", e);
      // Stay open if failed
    } finally {
      setIsSaving(false);
      setShowConfirm(false); // Close confirm modal if it was open
    }
